namespace Splash\Local\Objects\ThirdParty;

/**
 * Dolibarr ThirdParty Codes Fields
 *
 * Customer & Accountancy Codes are identifiers, not names.
 */
trait CodesTrait
{
    /**
     * Build Codes Fields using FieldFactory
     *
     * @return void
     */
    protected function buildCodesFields(): void
    {
        global $conf, $langs;

        //====================================================================//
        // Customer Code
        $this->fieldsFactory()->create(SPL_T_VARCHAR)
            ->identifier("code_client")
            ->name($langs->trans("CustomerCode"))
            ->description($langs->trans("CustomerCodeDesc"))
            ->microData("http://schema.org/Organization", "identifier")
            ->addOption('maxLength', "24")
            ->setPreferRead()
            ->isListed()
            ->isIndexed()
        ;
        //====================================================================//
        // Set as Read Only when Auto-Generated by Dolibarr
        if ("mod_codeproduct_leopard" != $conf->global->SOCIETE_CODECLIENT_ADDON) {
            $this->fieldsFactory()->isReadOnly();
        }
        //====================================================================//
        // Customer Accountancy Code
        // Always Read Only: Dolibarr only stores the Accountancy Code for
        // customers, and computes it whenever the Panicum addon is not used
        $this->fieldsFactory()->create(SPL_T_VARCHAR)
            ->identifier("code_compta_client")
            ->name($langs->trans("AccountancyCode"))
            ->microData("http://schema.org/Organization", "fiscalIdentifier")
            ->addOption('maxLength', "24")
            ->isReadOnly()
        ;
    }

    /**
     * Read requested Field
     *
     * @param string $key       Input List Key
     * @param string $fieldName Field Identifier / Name
     *
     * @return void
     */
    protected function getCodesFields(string $key, string $fieldName): void
    {
        //====================================================================//
        // READ Fields
        switch ($fieldName) {
            //====================================================================//
            // Direct Readings
            // Codes may be unset on Dolibarr side: expose an empty string, not null
            case 'code_client':
            case 'code_compta_client':
                $this->getSimple($fieldName, "object", "");

                break;
            default:
                return;
        }

        unset($this->in[$key]);
    }

    /**
     * Write Given Fields
     *
     * @param string      $fieldName Field Identifier / Name
     * @param null|string $fieldData Field Data
     *
     * @return void
     */
    protected function setCodesFields(string $fieldName, ?string $fieldData): void
    {
        //====================================================================//
        // WRITE Field
        switch ($fieldName) {
            //====================================================================//
            // Direct Writings
            case 'code_client':
                $this->setSimple($fieldName, $fieldData);

                break;
            default:
                return;
        }

        unset($this->in[$fieldName]);
    }
}
